from datetime import date

import pytest

from late_fee_calculator import LateFeeCalculator  # adjust module name

# 2026-01-05 is a Monday. Counting weekdays from it, 10 weekdays elapse
# by Mon 2026-01-19 (still in grace), so Tue 2026-01-20 is 1 billable day.
DUE = date(2026, 1, 5)
BIG = 2_000_000  # $20,000 -> 1000 cents/day at 0.05%/day (above min, below cap)


def calc(today):
    return LateFeeCalculator(today=today)


# ---------- constructor ----------

def test_init_uses_given_today():
    assert calc(date(2026, 3, 1))._today == date(2026, 3, 1)


def test_init_defaults_to_date_today():
    assert LateFeeCalculator()._today == date.today()


# ---------- _weekday_days_between ----------

@pytest.mark.parametrize(
    "start,end,expected",
    [
        (date(2026, 1, 5), date(2026, 1, 5), 0),    # same day
        (date(2026, 1, 6), date(2026, 1, 5), 0),    # end before start
        (date(2026, 1, 5), date(2026, 1, 6), 1),    # Mon -> Tue
        (date(2026, 1, 5), date(2026, 1, 12), 5),   # full week
        (date(2026, 1, 2), date(2026, 1, 5), 1),    # Fri -> Mon: only Fri counts
        (date(2026, 1, 3), date(2026, 1, 5), 0),    # Sat -> Mon: weekend only
        (date(2026, 1, 3), date(2026, 1, 4), 0),    # Sat -> Sun
    ],
)
def test_weekday_days_between(start, end, expected):
    assert calc(date(2026, 1, 1))._weekday_days_between(start, end) == expected


# ---------- zero-fee cases ----------

@pytest.mark.parametrize("balance", [0, -1, -100_000])
def test_non_positive_balance_returns_zero(balance):
    assert calc(date(2030, 1, 1)).compute_fee_cents(balance, DUE) == 0


def test_not_yet_due_returns_zero():
    assert calc(date(2026, 1, 1)).compute_fee_cents(BIG, DUE) == 0


def test_due_today_returns_zero():
    assert calc(DUE).compute_fee_cents(BIG, DUE) == 0


def test_last_day_of_grace_returns_zero():
    # exactly 10 weekdays late -> 0 billable days
    assert calc(date(2026, 1, 19)).compute_fee_cents(BIG, DUE) == 0


def test_within_grace_partial_returns_zero():
    assert calc(date(2026, 1, 12)).compute_fee_cents(BIG, DUE) == 0


# ---------- fee calculation ----------

def test_first_billable_day():
    assert calc(date(2026, 1, 20)).compute_fee_cents(BIG, DUE) == 1000


def test_multiple_billable_days():
    # Jan 24 (Sat) -> 15 weekdays late, 5 billable
    assert calc(date(2026, 1, 24)).compute_fee_cents(BIG, DUE) == 5000


def test_weekends_do_not_add_fee():
    sat = calc(date(2026, 1, 24)).compute_fee_cents(BIG, DUE)
    mon = calc(date(2026, 1, 26)).compute_fee_cents(BIG, DUE)
    assert sat == mon == 5000


@pytest.mark.parametrize(
    "balance,expected",
    [
        (2_000_600, 1000),  # raw 1000.3 -> rounds down
        (2_001_400, 1001),  # raw 1000.7 -> rounds up
    ],
)
def test_rounding_to_whole_cents(balance, expected):
    assert calc(date(2026, 1, 20)).compute_fee_cents(balance, DUE) == expected


# ---------- minimum fee ----------

def test_minimum_fee_applies_when_raw_fee_small():
    # 100,000 * 0.0005 = 50 cents raw -> bumped to 500
    assert calc(date(2026, 1, 20)).compute_fee_cents(100_000, DUE) == 500


def test_fee_above_minimum_not_raised():
    assert calc(date(2026, 1, 20)).compute_fee_cents(BIG, DUE) > 500


# ---------- maximum fee cap ----------

def test_fee_capped_at_25_percent_of_balance():
    # far in the future: raw fee would far exceed 25%
    fee = calc(date(2030, 1, 1)).compute_fee_cents(BIG, DUE)
    assert fee == int(BIG * 0.25) == 500_000


def test_fee_just_under_cap_not_capped():
    # ~11 weeks late: raw well below 25% of BIG
    fee = calc(date(2026, 3, 23)).compute_fee_cents(BIG, DUE)
    assert 0 < fee < 500_000


def test_minimum_overrides_cap_on_tiny_balance():
    # cap = 250 cents, min = 500 -> current behavior returns the minimum
    assert calc(date(2030, 1, 1)).compute_fee_cents(1_000, DUE) == 500
```

Notes:
- **Coverage:** these tests cover every branch: the non-positive balance guard, `end <= start`, the weekend/weekday split, the grace check, and the min/max clamps. That should be well above 90%. Run `pytest --cov=late_fee_calculator --cov-branch` to confirm.
- **Rounding tests:** they use fractional parts of .3 and .7 instead of exactly .5, to avoid float noise from `0.015 / 30`.
- **Minimum vs. cap:** `test_minimum_overrides_cap_on_tiny_balance` pins down a spec conflict. The docstring says the cap is a "hard cap", but the code applies the $5 minimum last, so a tiny balance can be charged more than 25%. If the cap should win, fix the code and flip that test's expected value.
